p("Absolute value", "E", "basics", "my_abs", "n", "Return the absolute value of `n` without calling the built-in `abs`.", ["If `n` is negative return `-n`."],
  "def my_abs(n):\n    return -n if n < 0 else n", "A conditional expression keeps it on one line.", [(5,), (-5,)], [(0,), (-2.5,), (3.25,)])
p("Maximum of three", "E", "conditionals", "max_of_three", "a, b, c", "Return the largest of three numbers without using `max`.", ["Compare step by step, keeping the best so far."],
  "def max_of_three(a, b, c):\n    best = a\n    if b > best:\n        best = b\n    if c > best:\n        best = c\n    return best", "Keep a running best and update it with each candidate.", [(1, 2, 3), (9, 4, 7)], [(-1, -5, -3), (5, 5, 5), (0, 10, 10)])
p("Sign of a number", "E", "conditionals", "sign", "n", "Return `1` if `n` is positive, `-1` if negative and `0` if zero.", ["Use `if / elif / else`."],
  "def sign(n):\n    if n > 0:\n        return 1\n    if n < 0:\n        return -1\n    return 0", "Three exclusive cases.", [(10,), (-3,)], [(0,), (0.1,), (-0.1,)])
p("Leap year", "E", "conditionals", "is_leap_year", "year", "Return `True` if `year` is a leap year in the Gregorian calendar: divisible by 4, except century years which must be divisible by 400.", ["Check 400 first, then 100, then 4."],
  "def is_leap_year(year):\n    if year % 400 == 0:\n        return True\n    if year % 100 == 0:\n        return False\n    return year % 4 == 0", "Order the checks from most to least specific.", [(2024,), (1900,)], [(2000,), (2023,), (2100,), (1996,)])
p("Grade letter", "E", "conditionals", "grade", "score", "Convert a numeric score to a letter: 90 and above `\"A\"`, 80-89 `\"B\"`, 70-79 `\"C\"`, 60-69 `\"D\"`, below 60 `\"F\"`.", ["Check from the highest threshold down."],
  "def grade(score):\n    if score >= 90:\n        return 'A'\n    if score >= 80:\n        return 'B'\n    if score >= 70:\n        return 'C'\n    if score >= 60:\n        return 'D'\n    return 'F'", "Early returns make a clean ladder.", [(95,), (72,)], [(90,), (89,), (60,), (59,), (0,)])
p("Sum 1 to n", "E", "loops", "sum_to_n", "n", "Return the sum of the integers from 1 to `n` inclusive (0 if `n` is less than 1).", ["Loop with `range(1, n + 1)` or use the formula."],
  "def sum_to_n(n):\n    total = 0\n    for i in range(1, n + 1):\n        total += i\n    return total", "`range` is empty when n < 1, so the total stays 0.", [(5,), (10,)], [(0,), (1,), (100,), (-4,)])
p("Count down", "E", "loops", "count_down", "n", "Return the list `[n, n-1, ..., 1]`. For `n <= 0` return an empty list.", ["`range(n, 0, -1)` counts down."],
  "def count_down(n):\n    return list(range(n, 0, -1))", "A negative step walks backwards.", [(5,), (1,)], [(0,), (-2,), (8,)])
p("Multiplication table row", "E", "loops", "times_table", "n", "Return the list of the first 10 multiples of `n`: `[n*1, n*2, ..., n*10]`.", ["Use a loop or a comprehension over `range(1, 11)`."],
  "def times_table(n):\n    return [n * i for i in range(1, 11)]", "A list comprehension builds it in one line.", [(3,), (7,)], [(0,), (-2,), (12,)])
p("Sum of even numbers", "E", "loops", "sum_evens", "n", "Return the sum of all even integers from 1 to `n` inclusive.", ["Step by 2 starting at 2."],
  "def sum_evens(n):\n    return sum(range(2, n + 1, 2))", "`range(2, n + 1, 2)` yields only evens.", [(10,), (7,)], [(0,), (1,), (2,), (50,)])
p("Count digits", "E", "numbers", "count_digits", "n", "Return how many decimal digits the integer `n` has (ignore the sign; `0` has one digit).", ["Convert `abs(n)` to a string."],
  "def count_digits(n):\n    return len(str(abs(n)))", "String length of the absolute value.", [(12345,), (-90,)], [(0,), (7,), (1000000,)])
p("Reverse an integer", "E", "numbers", "reverse_int", "n", "Reverse the digits of a non-negative integer. `120` becomes `21`.", ["Build the result with `% 10` and `// 10`, or reverse the string."],
  "def reverse_int(n):\n    r = 0\n    while n > 0:\n        r = r * 10 + n % 10\n        n //= 10\n    return r", "Peel off the last digit each time and append it to the result.", [(123,), (120,)], [(0,), (5,), (9001,), (987654321,)])
p("Is palindrome number", "E", "numbers", "is_palindrome_number", "n", "Return `True` if the non-negative integer `n` reads the same forwards and backwards.", ["Compare the string with its reverse."],
  "def is_palindrome_number(n):\n    s = str(n)\n    return s == s[::-1]", "`s[::-1]` reverses a string.", [(121,), (123,)], [(0,), (10,), (1221,), (12321,)])
p("Digital root", "E", "numbers", "digital_root", "n", "Repeatedly sum the digits of the non-negative integer `n` until a single digit remains, and return it.", ["Loop while `n >= 10`."],
  "def digital_root(n):\n    while n >= 10:\n        n = sum(int(c) for c in str(n))\n    return n", "Stop once only one digit is left.", [(38,), (5,)], [(0,), (99999,), (493193,), (10,)])
p("Greatest common divisor", "E", "number-theory", "gcd", "a, b", "Return the greatest common divisor of two positive integers without using `math.gcd`.", ["Euclid: replace `(a, b)` by `(b, a % b)` until `b` is 0."],
  "def gcd(a, b):\n    while b:\n        a, b = b, a % b\n    return a", "Euclid's algorithm runs in logarithmic time.", [(12, 18), (7, 13)], [(100, 75), (1, 1), (48, 36)], lambda r: (r.randint(1, 200), r.randint(1, 200)))
p("Least common multiple", "E", "number-theory", "lcm", "a, b", "Return the least common multiple of two positive integers.", ["`a * b // gcd(a, b)`."],
  "def lcm(a, b):\n    x, y = a, b\n    while y:\n        x, y = y, x % y\n    return a * b // x", "Use the GCD to avoid searching.", [(4, 6), (3, 5)], [(1, 9), (12, 18), (21, 6)])
p("Is prime", "E", "number-theory", "is_prime", "n", "Return `True` if the integer `n` is prime (numbers below 2 are not prime).", ["Only test divisors up to the square root."],
  "def is_prime(n):\n    if n < 2:\n        return False\n    i = 2\n    while i * i <= n:\n        if n % i == 0:\n            return False\n        i += 1\n    return True", "A composite number has a divisor no larger than its square root.", [(7,), (9,)], [(1,), (2,), (0,), (97,), (100,), (7919,)])
p("Next prime", "M", "number-theory", "next_prime", "n", "Return the smallest prime strictly greater than `n` (`n >= 0`).", ["Test candidates upward with a primality helper."],
  "def next_prime(n):\n    def is_prime(k):\n        if k < 2:\n            return False\n        i = 2\n        while i * i <= k:\n            if k % i == 0:\n                return False\n            i += 1\n        return True\n    n += 1\n    while not is_prime(n):\n        n += 1\n    return n", "Prime gaps are small, so linear search is fast.", [(10,), (2,)], [(0,), (13,), (89,), (1000,)])
p("Prime factors", "M", "number-theory", "prime_factors", "n", "Return the prime factorisation of `n >= 2` as a sorted list with repeats, e.g. `12` -> `[2, 2, 3]`.", ["Divide out each factor while it divides evenly."],
  "def prime_factors(n):\n    out = []\n    d = 2\n    while d * d <= n:\n        while n % d == 0:\n            out.append(d)\n            n //= d\n        d += 1\n    if n > 1:\n        out.append(n)\n    return out", "After removing small factors, any remainder above 1 is prime.", [(12,), (13,)], [(2,), (100,), (360,), (9973,), (1001,)])
p("Number of divisors", "M", "number-theory", "count_divisors", "n", "Return how many positive integers divide `n` evenly (`n >= 1`).", ["Pair each divisor `d` with `n // d`."],
  "def count_divisors(n):\n    count = 0\n    i = 1\n    while i * i <= n:\n        if n % i == 0:\n            count += 1 if i * i == n else 2\n        i += 1\n    return count", "Divisors come in pairs below and above the square root.", [(12,), (16,)], [(1,), (97,), (360,), (1000,)])
p("Perfect number check", "E", "number-theory", "is_perfect", "n", "Return `True` if `n` equals the sum of its proper divisors (excluding itself). 6 and 28 are perfect.", ["Sum divisors from 1 up to n // 2."],
  "def is_perfect(n):\n    if n < 2:\n        return False\n    return sum(d for d in range(1, n // 2 + 1) if n % d == 0) == n", "Proper divisors are at most n / 2.", [(6,), (12,)], [(28,), (1,), (496,), (8128,), (100,)])
p("Armstrong number", "E", "numbers", "is_armstrong", "n", "Return `True` if `n` equals the sum of its digits each raised to the power of the digit count (153 = 1³ + 5³ + 3³).", ["Get the digit count from `len(str(n))`."],
  "def is_armstrong(n):\n    s = str(n)\n    return sum(int(c) ** len(s) for c in s) == n", "Generalises to any digit count.", [(153,), (154,)], [(9,), (370,), (9474,), (100,), (0,)])
p("Celsius table", "E", "loops", "temperature_table", "start, stop, step", "Return a list of `[celsius, fahrenheit]` pairs for celsius from `start` to `stop` inclusive in increments of `step` (a positive integer). Fahrenheit is `c * 9 / 5 + 32`.", ["Use `range(start, stop + 1, step)`."],
  "def temperature_table(start, stop, step):\n    return [[c, c * 9 / 5 + 32] for c in range(start, stop + 1, step)]", "Inclusive stop requires `stop + 1`.", [(0, 20, 10), (-10, 10, 10)], [(0, 0, 1), (30, 40, 5), (-40, -30, 2)])
p("Collatz steps", "M", "loops", "collatz_steps", "n", "Starting from `n >= 1`, repeatedly halve even numbers or replace odd numbers with `3n + 1`. Return how many steps are needed to reach 1.", ["Count loop iterations until n is 1."],
  "def collatz_steps(n):\n    steps = 0\n    while n != 1:\n        n = n // 2 if n % 2 == 0 else 3 * n + 1\n        steps += 1\n    return steps", "The sequence is conjectured to always reach 1; for small inputs it does.", [(6,), (1,)], [(7,), (27,), (97,), (2,)])
p("Triangular number check", "M", "math", "is_triangular", "n", "Return `True` if `n >= 0` is a triangular number (1, 3, 6, 10, ... and 0).", ["Add 1, 2, 3, ... until you reach or pass n."],
  "def is_triangular(n):\n    total, k = 0, 0\n    while total < n:\n        k += 1\n        total += k\n    return total == n", "Accumulate triangular numbers until reaching n.", [(10,), (11,)], [(0,), (1,), (2,), (28,), (5050,), (5051,)])
p("Integer square root", "M", "math", "int_sqrt", "n", "Return the largest integer `r` with `r * r <= n` (`n >= 0`) without using `math.sqrt` or `**0.5`.", ["Binary search on r between 0 and n."],
  "def int_sqrt(n):\n    lo, hi = 0, n\n    while lo < hi:\n        mid = (lo + hi + 1) // 2\n        if mid * mid <= n:\n            lo = mid\n        else:\n            hi = mid - 1\n    return lo", "Binary search avoids floating point errors.", [(16,), (17,)], [(0,), (1,), (2,), (99,), (10**12,)])
p("Power without operator", "M", "math", "power", "base, exp", "Compute `base ** exp` for a non-negative integer `exp` using repeated squaring (no `**` or `pow`).", ["If exp is even: square the half power."],
  "def power(base, exp):\n    result = 1\n    while exp > 0:\n        if exp & 1:\n            result *= base\n        base *= base\n        exp >>= 1\n    return result", "Repeated squaring needs only O(log exp) multiplications.", [(2, 10), (3, 4)], [(5, 0), (0, 5), (-2, 3), (7, 1), (10, 12)])
p("Sum of squares", "E", "loops", "sum_of_squares", "n", "Return `1² + 2² + ... + n²` (0 if `n < 1`).", ["Loop and accumulate `i * i`."],
  "def sum_of_squares(n):\n    return sum(i * i for i in range(1, n + 1))", "A generator expression sums lazily.", [(3,), (10,)], [(0,), (1,), (100,)])
p("Number of steps to zero", "E", "loops", "steps_to_zero", "n", "Given a non-negative integer `n`, each step halves it if even, otherwise subtracts one. Return the steps to reach 0.", ["Loop until n is 0."],
  "def steps_to_zero(n):\n    steps = 0\n    while n:\n        n = n // 2 if n % 2 == 0 else n - 1\n        steps += 1\n    return steps", "Each pair of steps roughly halves the number.", [(14,), (8,)], [(0,), (1,), (123,), (1000,)])
p("Is power of two", "E", "bit-manipulation", "is_power_of_two", "n", "Return `True` if the integer `n` is a positive power of two.", ["A power of two has exactly one bit set: `n & (n - 1) == 0`."],
  "def is_power_of_two(n):\n    return n > 0 and n & (n - 1) == 0", "Clearing the lowest bit leaves zero only for powers of two.", [(16,), (18,)], [(1,), (0,), (-8,), (1024,), (1023,)])
p("Hours minutes seconds", "E", "numbers", "format_duration", "seconds", "Convert a non-negative number of seconds to `\"H:MM:SS\"` (hours not zero-padded, minutes and seconds two digits).", ["Use `divmod` twice and format with `:02d`."],
  "def format_duration(seconds):\n    m, s = divmod(seconds, 60)\n    h, m = divmod(m, 60)\n    return f'{h}:{m:02d}:{s:02d}'", "`divmod` returns quotient and remainder at once.", [(3661,), (59,)], [(0,), (3600,), (86399,), (360000,)])
p("Change counter", "E", "numbers", "coins_greedy", "cents", "Return the minimum number of US coins (25, 10, 5, 1 cents) that add up to `cents`.", ["Take as many large coins as possible first."],
  "def coins_greedy(cents):\n    count = 0\n    for c in (25, 10, 5, 1):\n        count += cents // c\n        cents %= c\n    return count", "Greedy is optimal for this coin system.", [(41,), (3,)], [(0,), (99,), (100,), (30,)])
p("Simple interest and compound", "E", "math", "compound_interest", "principal, rate, years", "Return the final amount after compounding once a year: `principal * (1 + rate) ** years`, rounded to 2 decimals. `rate` is a fraction like `0.05`.", ["Use `round(x, 2)`."],
  "def compound_interest(principal, rate, years):\n    return round(principal * (1 + rate) ** years, 2)", "Rounding happens once at the end.", [(1000, 0.05, 2), (500, 0.1, 1)], [(100, 0.0, 10), (2000, 0.03, 5), (1, 1, 10)])
p("BMI category", "E", "conditionals", "bmi_category", "weight_kg, height_m", "Compute BMI = weight / height² and return `\"underweight\"` (< 18.5), `\"normal\"` (< 25), `\"overweight\"` (< 30) or `\"obese\"`.", ["Compute once, then use a ladder of comparisons."],
  "def bmi_category(weight_kg, height_m):\n    bmi = weight_kg / (height_m ** 2)\n    if bmi < 18.5:\n        return 'underweight'\n    if bmi < 25:\n        return 'normal'\n    if bmi < 30:\n        return 'overweight'\n    return 'obese'", "Boundaries are exclusive on the upper end.", [(70, 1.75), (50, 1.8)], [(90, 1.7), (100, 1.7), (60, 1.6), (45, 1.6)])
p("Quadratic roots count", "E", "math", "count_real_roots", "a, b, c", "For `a*x² + b*x + c = 0` with `a != 0` return the number of distinct real roots (0, 1 or 2).", ["Use the discriminant `b*b - 4*a*c`."],
  "def count_real_roots(a, b, c):\n    d = b * b - 4 * a * c\n    if d > 0:\n        return 2\n    if d == 0:\n        return 1\n    return 0", "Sign of the discriminant decides.", [(1, -3, 2), (1, 2, 1)], [(1, 0, 1), (2, 4, 2), (-1, 0, 4), (1, 1, 1)])
p("Triangle type", "E", "conditionals", "triangle_type", "a, b, c", "Given three side lengths return `\"invalid\"` if they cannot form a triangle (sum of two sides must exceed the third), otherwise `\"equilateral\"`, `\"isosceles\"` or `\"scalene\"`.", ["Validate first, then count equal sides."],
  "def triangle_type(a, b, c):\n    if a + b <= c or a + c <= b or b + c <= a:\n        return 'invalid'\n    if a == b == c:\n        return 'equilateral'\n    if a == b or b == c or a == c:\n        return 'isosceles'\n    return 'scalene'", "Strict inequality rejects degenerate triangles.", [(3, 3, 3), (3, 4, 5)], [(2, 2, 3), (1, 2, 3), (5, 5, 1), (1, 1, 10)])
p("Days in month", "E", "conditionals", "days_in_month", "year, month", "Return the number of days in `month` (1-12) of `year`, handling leap years.", ["February has 29 days in leap years."],
  "def days_in_month(year, month):\n    if month == 2:\n        leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)\n        return 29 if leap else 28\n    return 30 if month in (4, 6, 9, 11) else 31", "Only February depends on the year.", [(2024, 2), (2023, 2)], [(2023, 1), (2023, 4), (1900, 2), (2000, 2), (2023, 12)])
p("Day of year", "M", "numbers", "day_of_year", "year, month, day", "Return which day of the year (1-366) the date falls on.", ["Add up the lengths of the previous months."],
  "def day_of_year(year, month, day):\n    leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)\n    lengths = [31, 29 if leap else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]\n    return sum(lengths[: month - 1]) + day", "Slice the month lengths before the current month.", [(2023, 1, 1), (2024, 3, 1)], [(2023, 12, 31), (2024, 12, 31), (2023, 3, 1), (1900, 3, 1)])
p("Weekday name", "M", "numbers", "weekday_name", "days_since_monday", "Given the number of days since a known Monday (any non-negative integer), return the weekday name (`\"Monday\"`, ..., `\"Sunday\"`).", ["Index a list with `n % 7`."],
  "def weekday_name(days_since_monday):\n    names = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']\n    return names[days_since_monday % 7]", "Modulo wraps the week around.", [(0,), (6,)], [(7,), (10,), (100,), (3,)])
p("Swap values", "E", "basics", "swap_pair", "a, b", "Return the two values swapped as a list `[b, a]`.", ["Return them in reverse order."],
  "def swap_pair(a, b):\n    return [b, a]", "Python can also swap in place with `a, b = b, a`.", [(1, 2), ('x', 'y')], [(0, 0), ([1], [2]), (None, 5)])
p("Min and max pair", "E", "basics", "min_max", "a, b, c", "Return `[smallest, largest]` of the three numbers.", ["Use `min` and `max`."],
  "def min_max(a, b, c):\n    return [min(a, b, c), max(a, b, c)]", "Built-ins accept multiple arguments.", [(3, 1, 2), (5, 5, 5)], [(-1, -9, 0), (100, 50, 75), (2, 9, 4)])
p("Average of numbers", "E", "basics", "mean", "numbers", "Return the arithmetic mean of a non-empty list of numbers.", ["`sum(numbers) / len(numbers)`."],
  "def mean(numbers):\n    return sum(numbers) / len(numbers)", "True division returns a float.", [([1, 2, 3],), ([10],)], [([1, 2],), ([-4, 4],), ([2.5, 3.5, 4.5],)])
p("Clamp a value", "E", "conditionals", "clamp", "x, low, high", "Return `x` limited to the closed range `[low, high]` (`low <= high`).", ["`max(low, min(x, high))`."],
  "def clamp(x, low, high):\n    return max(low, min(x, high))", "Min then max keeps x inside the bounds.", [(5, 0, 10), (-3, 0, 10)], [(15, 0, 10), (0, 0, 10), (10, 0, 10), (2.5, 1, 2)])
p("FizzBuzz custom", "E", "loops", "fizzbuzz_custom", "n, a, b", "Like FizzBuzz for `1..n`, but using divisors `a` and `b`: `\"Fizz\"` for multiples of `a`, `\"Buzz\"` for multiples of `b`, `\"FizzBuzz\"` for both, otherwise the number as a string.", ["Build the word from parts."],
  "def fizzbuzz_custom(n, a, b):\n    out = []\n    for i in range(1, n + 1):\n        s = ('Fizz' if i % a == 0 else '') + ('Buzz' if i % b == 0 else '')\n        out.append(s or str(i))\n    return out", "Concatenating optional parts handles the combined case automatically.", [(6, 2, 3), (5, 5, 7)], [(0, 2, 3), (15, 3, 5), (10, 4, 6)])
p("Rock paper scissors", "E", "conditionals", "rps_winner", "a, b", "Players choose `\"rock\"`, `\"paper\"` or `\"scissors\"`. Return `1` if player A wins, `2` if player B wins, `0` for a draw.", ["Rock beats scissors, scissors beats paper, paper beats rock."],
  "def rps_winner(a, b):\n    if a == b:\n        return 0\n    wins = {('rock', 'scissors'), ('scissors', 'paper'), ('paper', 'rock')}\n    return 1 if (a, b) in wins else 2", "A set of winning pairs makes the rule data.", [('rock', 'paper'), ('rock', 'rock')], [('scissors', 'paper'), ('paper', 'rock'), ('scissors', 'rock'), ('paper', 'scissors')])
